import React from 'react';
import { Button, StyleSheet, View } from 'react-native';
import * as Print from 'expo-print';
import * as Sharing from 'expo-sharing';
import Duty from '../duty/Duty';

const PdfGeneratorMobile: React.FC = ({
  designation,
  payBand,
  level,
  rateOfPay,
  selectedMonth,
  duties,
}) => {
  const footerText = "This is generated by Allowance Calculator Platform by Feyntech Optimization Solutions Pvt. Ltd.";

  const generatePDF = async () => {
    const html = `
      <!DOCTYPE html>
      <html>
        <head>
          <meta charset="UTF-8">
          <title>Duty Report</title>
          <style>
            body {
              font-family: Arial, sans-serif;
              font-size: 10pt;
              margin: 0;
              padding: 0;
            }
            header, footer {
              text-align: right;
              margin: 10px 20px;
            }
            h1, h2 {
              text-align: center;
            }
            table {
              width: 100%;
              border-collapse: collapse;
              margin-top: 10px;
            }
            th, td {
              border: 1px solid black;
              padding: 5px;
              text-align: left;
            }
            th {
              background-color: #C8E6F5;
              font-weight: bold;
            }
            .summary-block {
              margin-top: 20px;
            }
          </style>
        </head>
        <body>
          <header>${new Date().toLocaleString()}</header>
          <h1>Duty Report</h1>
          <table>
            <thead>
              <tr>
                <th>Designation</th>
                <th>Pay Band</th>
                <th>Level</th>
                <th>Rate of Pay</th>
                <th>Selected Month</th>
              </tr>
            </thead>
            <tbody>
              <tr>
                <td>${designation}</td>
                <td>${payBand}</td>
                <td>${level}</td>
                <td>${rateOfPay}</td>
                <td>${selectedMonth}</td>
              </tr>
            </tbody>
          </table>

          ${duties.map((duty, index) => `
            <h2>Duty ${index + 1}</h2>
            <table>
              <thead>
                <tr>
                  <th>Date</th>
                  <th>Type of Work</th>
                  <th>Train No.</th>
                  <th>Dep. Time</th>
                  <th>Arr. Time</th>
                  <th>Source</th>
                  <th>Dest.</th>
                  <th>Distance</th>
                  <th>Duty Hours</th>
                  <th>Allowance</th>
                  <th>Remarks</th>
                </tr>
              </thead>
              <tbody>
                ${duty.trips.map(trip => `
                  <tr>
                    <td>${trip.date}</td>
                    <td>${trip.typeOfWork}</td>
                    <td>${trip.trainNumber}</td>
                    <td>${trip.departureTime}</td>
                    <td>${trip.arrivalTime}</td>
                    <td>${trip.sourceStation}</td>
                    <td>${trip.destinationStation}</td>
                    <td>${trip.distance}</td>
                    <td>${trip.dutyHours}</td>
                    <td>${trip.allowance}</td>
                    <td>${trip.remarks}</td>
                  </tr>
                `).join('')}
              </tbody>
            </table>
          `).join('')}

          <footer>${footerText}</footer>
        </body>
      </html>
    `;

    const { uri } = await Print.printToFileAsync({
      html,
      orientation: 'landscape'
    });

    console.log('PDF generated:', uri);

    await Sharing.shareAsync(uri, {
      mimeType: 'application/pdf',
      dialogTitle: 'Share your PDF',
      UTI: 'com.adobe.pdf'
    });
  };

  return (
    <View style={styles.container}>
      <Button title="Generate PDF" onPress={generatePDF} />
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
  }
});

export default PdfGeneratorMobile;
